"use client";

import { useEffect, useRef } from "react";
import Image from "next/image";
import Link from "next/link";
import { titleHref } from "@/lib/title-utils";

const TMDB_IMAGE = "https://image.tmdb.org/t/p/w500";

export interface DayEntry {
  tmdbId: number;
  title: string;
  posterPath: string | null;
  mediaType: string;
  rating: number;
  runtime: number | null;
  episodeCount: number;
}

interface DayPopupProps {
  date: string;
  entries: DayEntry[];
  onClose: () => void;
}

function formatRuntime(totalMinutes: number): string {
  const h = Math.floor(totalMinutes / 60);
  const m = totalMinutes % 60;
  if (h === 0) return `${m}m`;
  if (m === 0) return `${h}h`;
  return `${h}h ${m}m`;
}

function formatDate(dateStr: string): string {
  return new Date(dateStr + "T12:00:00").toLocaleDateString("en-US", {
    weekday: "long",
    month: "long",
    day: "numeric",
    year: "numeric",
  });
}

export default function DayPopup({ date, entries, onClose }: DayPopupProps) {
  const overlayRef = useRef<HTMLDivElement>(null);
  const mountedRef = useRef(false);

  useEffect(() => {
    mountedRef.current = true;
    function onKeyDown(e: KeyboardEvent) {
      if (e.key === "Escape") onClose();
    }
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [onClose]);

  // Total runtime
  const totalMinutes = entries.reduce((sum, e) => {
    if (e.runtime) return sum + e.runtime * e.episodeCount;
    // fallback estimates
    if (e.mediaType === "movie") return sum + 120;
    if (e.mediaType === "anime") return sum + 24 * e.episodeCount;
    return sum + 45 * e.episodeCount;
  }, 0);

  return (
    <div
      ref={overlayRef}
      className="fixed inset-0 z-[100] flex items-center justify-center p-4"
      onClick={(e) => {
        if (e.target === overlayRef.current) onClose();
      }}
    >
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" />

      {/* Popup */}
      <div className="relative w-full max-w-md bg-bg-card border border-border rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 fade-in duration-200">
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-border">
          <h3 className="text-text-primary font-semibold text-sm">
            {formatDate(date)}
          </h3>
          <button
            onClick={onClose}
            className="w-7 h-7 flex items-center justify-center rounded-full bg-bg-card-hover text-text-secondary hover:bg-bg-surface hover:text-text-primary transition-colors text-sm"
          >
            ✕
          </button>
        </div>

        {/* Poster row */}
        <div className="px-5 py-4">
          <div className="grid grid-cols-4 gap-3 justify-center">
            {entries.slice(0, 8).map((entry) => (
              <Link
                key={`${entry.tmdbId}-${entry.mediaType}`}
                href={titleHref(entry.tmdbId, entry.mediaType)}
                className="flex flex-col items-center gap-2 group w-[88px]"
              >
                <div className="w-[80px] aspect-[2/3] rounded-lg overflow-hidden bg-bg-primary relative shadow-lg group-hover:ring-2 ring-accent transition-all">
                  {entry.posterPath ? (
                    <Image
                      src={entry.posterPath.startsWith("http") ? entry.posterPath : `${TMDB_IMAGE}${entry.posterPath}`}
                      alt={entry.title}
                      fill
                      className="object-cover"
                      sizes="80px"
                      unoptimized
                    />
                  ) : (
                    <div className="absolute inset-0 bg-gradient-to-br from-indigo-600 to-purple-800 flex items-center justify-center p-1">
                      <span className="text-text-primary/60 text-[9px] font-semibold text-center leading-tight">
                        {entry.title}
                      </span>
                    </div>
                  )}
                </div>
                <div className="text-center w-full">
                  <p className="text-text-primary text-[11px] font-medium truncate leading-tight max-w-[80px]">
                    {entry.title}
                  </p>
                  {entry.rating > 0 && (
                    <p className="text-gold text-[10px] mt-0.5">
                      ★ {entry.rating}
                    </p>
                  )}
                  {entry.runtime && (
                    <p className="text-text-secondary text-[10px]">
                      {entry.mediaType === "movie"
                        ? formatRuntime(entry.runtime)
                        : formatRuntime(entry.runtime * entry.episodeCount)}
                    </p>
                  )}
                </div>
              </Link>
            ))}
          </div>
        </div>

        {/* Total time */}
        <div className="px-5 py-3 border-t border-border bg-bg-primary/50">
          <div className="flex items-center justify-between text-sm">
            <span className="text-text-secondary">Total watch time</span>
            <span className="text-text-primary font-semibold">
              {formatRuntime(totalMinutes)}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}
